# Ports that are Alpine packages rather than from-source builds.
#
#   <port> <alpine package>...
#
# <port> is the name the rest of the tree already uses — the directory under
# build/$ARCH/pkg and the name in every -I/-L path. The packages after it are
# what Alpine actually splits that library into, which is finer than the ports
# were: the runtime shared library, the -dev headers and .so symlink, and the
# -static archive are three packages, and a library with several archives (webp,
# pcre2) has one per archive. Ask for too few and a -dev symlink points at
# nothing — tools/packages/alpine-fetch.sh fails on exactly that rather than
# letting the linker fall back to the static archive.
#
# Read by tools/packages/pkg-prefix.sh. See docs/ports-migration-plan.md.

musl          musl musl-dev linux-headers
zlib          zlib zlib-dev zlib-static
expat         libexpat expat-dev expat-static
pcre2         pcre2 libpcre2-16 libpcre2-32 pcre2-dev
brotli        brotli-libs brotli-dev brotli-static
libunistring  libunistring libunistring-dev libunistring-static
libidn2       libidn2 libidn2-dev libidn2-static
libpsl        libpsl libpsl-dev libpsl-static
libpng        libpng libpng-dev libpng-static
libjpeg       libjpeg-turbo libturbojpeg libjpeg-turbo-dev libjpeg-turbo-static
libwebp       libwebp libsharpyuv libwebpdecoder libwebpdemux libwebpmux libwebp-dev libwebp-static

# M49. Upstream libwayland, shared — the port built it into a static archive
# together with a static libffi, and Alpine's libffi.a is not built -fPIC, so a
# PIE cannot link it. Both are shared here, which is what they are meant to be.
# wayland-dev also carries the generated protocol headers the port's own
# wayland-scanner run used to produce.
wayland       wayland-libs-client wayland-libs-server wayland-libs-cursor wayland-libs-egl wayland-dev
libffi        libffi libffi-dev

# M51 desktop/text stack. Alpine's harfbuzz archive carries no C++ runtime
# references, so it links into these C binaries the way the HB_TINY port did.
freetype      freetype freetype-dev freetype-static
fontconfig    fontconfig fontconfig-dev fontconfig-static
harfbuzz      harfbuzz harfbuzz-dev harfbuzz-static
pixman        pixman pixman-dev pixman-static
xkbcommon     libxkbcommon libxkbcommon-dev libxkbcommon-static

# M51 cairo. Alpine's cairo is built with the X11 backend; those .so files are
# staged into rootfs/lib the same way every other pkg .so is, and the image is
# large enough to carry them. libx11/libxcb/libxrender entries below ensure the
# transitive deps are present both at link time and at runtime.
cairo         cairo cairo-dev
libx11        libx11 libx11-dev
libxext       libxext libxext-dev
libxrender    libxrender libxrender-dev
libxcb        libxcb libxcb-dev

# M53 codecs and TLS. libvpx is in community.
libvpx        repo:community libvpx libvpx-dev
mbedtls       mbedtls mbedtls-dev mbedtls-static
openssl       openssl libssl3 libcrypto3 openssl-dev openssl-libs-static

# M104 PAM (Linux-PAM + pam_unix.so).
pam           linux-pam linux-pam-dev

# Programs installed onto the image rather than linked against. Used with
# ALPINE_LAYOUT=native, so they keep their own paths, into one staging root that
# the root-image rule copies over the image.
#
# dropbear is four packages because Alpine ships each tool separately rather
# than as one multi-call binary; busybox-binsh is the /bin/sh symlink.
# openrc and runit are deliberately absent. Alpine's openrc brings its own
# /lib/rc, /etc/init.d and runlevels, which replaced this image's and took the
# boot straight to poweroff; and their runit is statically linked, which the
# rootfs gate rejects outright (tools/check-dynamic.sh). Both keep their ports:
# what they do is the running system's behaviour, not a build artefact.
#
# Mesa's userspace is named here rather than left to the SONAME closure, which
# is what used to drag it in: wlroots records libEGL.so.1, libgbm.so.1 and
# libGLESv2.so.2, and Xwayland records libgbm.so.1 and libGL.so.1, so without
# them sway does not start. It replaced tools/ports/build-mesa.sh — the same
# 24.0.9, built for the same musl and the same architecture, minus a 477 MB
# build tree and the duty to keep a meson cross-build working.
#
# mesa-dri-gallium is deliberately absent, and its absence is enforced by
# alpine.lock having no entry for it: it is 34 MB and pulls llvm17-libs (150 MB)
# behind it, for hardware drivers this image has no use for — composition is
# software (WLR_RENDERER=pixman) and the browser runs with --disable-gpu. When
# M102a gets to running the iris driver on a real Intel GPU, that is the point
# at which it earns its place — which is what the `gpudrv` group below is:
# opt-in, off by default, and pulled in by B1NIX_GPU_DRV=1.
programs      zsh curl libcurl samurai bmake dropbear dropbear-ssh \
              dropbear-scp dropbear-dbclient \
              seatd sway swaybg grim foot foot-extra-terminfo cage \
              font-dejavu xkeyboard-config xwayland \
              mesa-egl mesa-gles mesa-gbm mesa-gl mesa-glapi

# The browser. Baked into the image at build time rather than installed in the
# guest: the closure is ~175 packages and installing it over the network inside
# b1nix took longer than the hour a passthrough run gets. Off by default
# (B1NIX_BROWSER=1) because it is half a gigabyte that only the browser runs
# need. mesa-dri-gallium is skipped deliberately — see the note above; chromium
# runs with --disable-gpu, and pulling it would add 184 MB of driver and LLVM
# for hardware rendering this image cannot do yet. chromium-swiftshader is the
# 4 MB answer instead: --disable-gpu does not stop chromium starting a GPU
# process, that process needs a working EGL, and with no driver under libEGL it
# died with "Initialization of all EGL display types failed" and no window ever
# appeared.
browser       chromium chromium-swiftshader strace

# The hardware driver stack, for the runs that have hardware. mesa-dri-gallium
# carries iris — the Gen8/Gen9.5 Intel driver M102a exists to run — and drags
# llvm17-libs behind it, which is why it is not in `programs`: 184 MB is a lot
# to carry on every image for a driver most runs cannot use. B1NIX_GPU_DRV=1
# adds it, and the i915 passthrough run is what sets that.
# foot and the fonts it needs come with it: since each optional group stages
# into its own root, a driver image no longer inherits the terminal from
# whatever was built before it, and a compositor with no client to composite
# proves very little.
gpudrv        mesa-dri-gallium foot font-dejavu

# KDE. Not just the compositor: plasmashell brings the panel, the task manager,
# the desktop and the menu — a desktop rather than a window manager. kwin_wayland
# is a full Wayland compositor built on Qt6 and KF6, and it is
# the first desktop on this system that is not wlroots — a different renderer, a
# different input stack and a different set of assumptions about the kernel
# underneath, which is exactly why it is worth running. Opt-in
# (B1NIX_KDE=1) and its own staging root: the closure is Qt6 plus most of
# KDE Frameworks.
kde           repo:community kwin qt6-qtwayland kwayland-integration seatd \
              libgpg-error libxtst elfutils mesa-dri-gallium foot \
              font-dejavu xkeyboard-config \
              lcms2 libxi dbus-libs icu-libs icu-data-en double-conversion \
              libvorbis libltdl libgomp \
              dbus dbus-libs elogind libelogind sway swaybg grim \
              plasma-workspace plasma-desktop plasma-integration \
              kactivitymanagerd breeze breeze-icons kde-cli-tools \
              qt6-qtsvg kirigami libplasma util-linux-login eudev
              # libplasma, not plasma-framework: KF5's plasma-framework was
              # renamed for KF6 and no package by the old name exists in v3.20.
              #
              # util-linux-login carries the only /bin/login here that is
              # linked against libpam: kwin's DRM backend asks logind for its
              # devices, logind only answers a registered session, and a
              # session is created by pam_elogind.so during a PAM login.
              # BusyBox's login applet does no PAM, so without this the
              # compositor never issues a single open() on /dev/dri -- it
              # refuses before the kernel is involved at all. Staged to
              # /sbin/login-pam so the BusyBox applet keeps /bin/login.

# The curl library, for what links against it rather than runs it (NetSurf).
curlbuild     libcurl curl-dev curl-static
